INSERT INTO competencia_c8 (nombre, tipo_cs, descripcion, area) VALUES
('Pensamiento espacial y sistemas territoriales', 'Pensamiento espacial', 'Comprensión del espacio geográfico, orientación, lectura de mapas y relación entre territorio y sociedad.', 'Ciencias Sociales'),
('Pensamiento temporal y representaciones sociales', 'Pensamiento temporal', 'Manejo de conceptos de tiempo histórico, cambio, continuidad y memoria colectiva.', 'Ciencias Sociales'),
('Pensamiento social y crítico', 'Pensamiento crítico', 'Análisis de fenómenos sociales, económicos y culturales desde múltiples perspectivas.', 'Ciencias Sociales'),
('Ética, convivencia y ciudadanía', 'Ciudadanía', 'Reconocimiento de derechos, deberes, normas de convivencia y participación democrática.', 'Ciencias Sociales'),
('Relaciones con la historia y la cultura', 'Historia y cultura', 'Comprensión de procesos históricos locales, nacionales y mundiales, y su impacto cultural.', 'Ciencias Sociales'),
('Relaciones ético-políticas', 'Ética política', 'Análisis de estructuras de poder, democracia, derechos humanos y resolución de conflictos.', 'Ciencias Sociales'),
('Relaciones con el ambiente', 'Ambiente', 'Comprensión de la relación sociedad-naturaleza, problemáticas ambientales y desarrollo sostenible.', 'Ciencias Sociales'),
('Relaciones económicas y sociales', 'Economía y sociedad', 'Análisis de sistemas económicos, actividades productivas y organización social.', 'Ciencias Sociales');
